create table if not exists public.ls96_class (id uuid primary key default gen_random_uuid(), name text not null, code text unique not null default replace(gen_random_uuid()::text,'-',''), owner uuid not null);
create table if not exists public.ls96_member (cid uuid references public.ls96_class on delete cascade, member uuid not null, primary key(cid,member));
create table if not exists public.ls96_set (id uuid primary key default gen_random_uuid(), cid uuid references public.ls96_class on delete cascade, owner uuid not null, title text not null, subject text not null, cards jsonb not null, created timestamptz default now());
create table if not exists public.ls96_eventrow (id uuid primary key default gen_random_uuid(), cid uuid references public.ls96_class on delete cascade, title text not null, day date not null);
alter table public.ls96_class enable row level security;
alter table public.ls96_member enable row level security;
alter table public.ls96_set enable row level security;
alter table public.ls96_eventrow enable row level security;
create or replace function public.ls96_create(nm text) returns uuid language plpgsql security definer set search_path=public as $$ declare x uuid; begin if auth.uid() is null then raise exception 'Login erforderlich'; end if; insert into ls96_class(name,owner) values(left(nm,100),auth.uid()) returning id into x; insert into ls96_member values(x,auth.uid()); return x; end $$;
create or replace function public.ls96_join(invite text) returns uuid language plpgsql security definer set search_path=public as $$ declare x uuid; begin if auth.uid() is null then raise exception 'Login erforderlich'; end if; select id into x from ls96_class where code=invite; if x is null then raise exception 'Code ungültig'; end if; insert into ls96_member values(x,auth.uid()) on conflict do nothing; return x; end $$;
create or replace function public.ls96_classes() returns setof public.ls96_class language sql security definer set search_path=public as $$ select c.* from ls96_class c join ls96_member m on m.cid=c.id where m.member=auth.uid() $$;
create or replace function public.ls96_sets(cid uuid) returns setof public.ls96_set language sql security definer set search_path=public as $$ select s.* from ls96_set s where auth.uid() is not null and s.cid is not distinct from $1 and ($1 is null or exists(select 1 from ls96_member m where m.cid=$1 and m.member=auth.uid())) order by s.created desc $$;
create or replace function public.ls96_publish(cid uuid,ttl text,sub text,items jsonb) returns void language plpgsql security definer set search_path=public as $$ begin if auth.uid() is null or ($1 is not null and not exists(select 1 from ls96_member m where m.cid=$1 and m.member=auth.uid())) then raise exception 'Kein Zugriff'; end if; if jsonb_typeof(items)<>'array' then raise exception 'Ungültige Karten'; end if; insert into ls96_set(cid,owner,title,subject,cards) values($1,auth.uid(),left(ttl,150),left(sub,100),items); end $$;
create or replace function public.ls96_remove(sid uuid) returns void language sql security definer set search_path=public as $$ delete from ls96_set where id=$1 and owner=auth.uid() $$;
create or replace function public.ls96_events(cid uuid) returns setof public.ls96_eventrow language sql security definer set search_path=public as $$ select e.* from ls96_eventrow e where e.cid=$1 and exists(select 1 from ls96_member m where m.cid=$1 and m.member=auth.uid()) order by e.day $$;
create or replace function public.ls96_event(cid uuid,ttl text,dt date) returns void language plpgsql security definer set search_path=public as $$ begin if not exists(select 1 from ls96_member m where m.cid=$1 and m.member=auth.uid()) then raise exception 'Kein Zugriff'; end if; insert into ls96_eventrow(cid,title,day) values($1,left(ttl,150),dt); end $$;
